d3 = [[5]*15 for _ in range(15)]
pts=[(1,8),(1,13),(3,3),(3,8),(4,6),(6,6),(6,7),(6,13),(7,1),(7,5),(7,6),(8,6),(8,7),(9,3),(10,6),(10,13),(12,1),(12,3)]
for r,c in pts:d3[r][c]=6
out3pts=[(4,6),(5,5),(5,6),(5,7),(6,5),(6,7)]
def comps(a,conn=4):
    H,W=len(a),len(a[0]); s={(r,c) for r in range(H) for c in range(W) if a[r][c]!=5}
    d=[]
    while s:
        stack=[s.pop()]; comp=set(stack)
        while stack:
            r,c=stack.pop()
            for dr in range(-1,2):
              for dc in range(-1,2):
                if (conn==8 or abs(dr)+abs(dc)==1) and (r+dr,c+dc) in s:
                  q=(r+dr,c+dc);s.remove(q);comp.add(q);stack.append(q)
        d.append(comp)
    return sorted(d,key=len,reverse=True)
for conn in [4,8]:
    print(conn, [len(x) for x in comps(d3,conn)], comps(d3,conn)[:2])

# Conway Life step on D3 foreground
alive={(r,c) for r,c in pts}
life=set()
for r in range(15):
 for c in range(15):
  n=sum((r+dr,c+dc) in alive for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0))
  if n==3 or ((r,c) in alive and n==2): life.add((r,c))
print('life', sorted(life), 'target?', set(out3pts)==life)

